#[test]
fn l8merge2_two_token_boxes_sharing_one_new_change_output_go_before_three_boxes() {
    use seedelf_core::assets::Asset as Token;
    const OTHER_POLICY: &str = "d0d0d0d0d0d0d0d0d0d0d0d0d0d0d0d0d0d0d0d0d0d0d0d0d0d0d0d0";
    let w = world();
    let p = &w.chain.params;
    let of_other_policy = |mut u: UtxoResponse| { for a in u.asset_list.iter_mut().flatten() { a.policy_id = OTHER_POLICY.to_string(); } u };
    let bundle_names: Vec<String> = (0..20).map(|i| format!("m{i:02}")).collect();
    let bundle: Vec<(&str, u64)> = bundle_names.iter().map(|n| (n.as_str(), 1)).collect();
    let twenty = bundle.iter().fold(Assets::new(), |all, (name, q)| all.add(Token::new(TOKEN_POLICY.to_string(), hex::encode(name), *q).unwrap()).unwrap());
    let least20 = build::minimum_deposit(p, &twenty).unwrap();
    let (mut wrong, mut skipped, mut checked) = (Vec::new(), Vec::new(), 0usize);
    for (m_ada, t_ada, a_ada) in [(least20 + 500_000, 6_500_000u64, 5_500_000u64), (least20, 6_500_000, 5_500_000), (least20 + 500_000, 11_000_000, BOX), (least20, 11_000_000, BOX)] {
        for (kind, n1, n2, other) in [("one token", "pooltoken", "pooltoken", false), ("two names of one policy", "poolA", "poolB", false), ("two policies", "poolA", "poolB", true)] {
            let m = owned(&w, 0x23, 0, m_ada, &bundle);
            let t1 = owned(&w, 0x70, 0, t_ada, &[(n1, 1)]);
            let t2 = { let u = owned(&w, 0x71, 0, t_ada, &[(n2, 1)]); if other { of_other_policy(u) } else { u } };
            let a = owned(&w, 0x31, 0, a_ada, &[]);
            let b = owned(&w, 0x32, 0, a_ada, &[]);
            let names = [(&m, "M"), (&t1, "T1"), (&t2, "T2"), (&a, "A"), (&b, "B")];
            let called = |s: &[UtxoResponse]| { let mut v: Vec<&str> = s.iter().map(|x| names.iter().find(|(n, _)| n.tx_hash == x.tx_hash).map_or("?", |(_, k)| *k)).collect(); v.sort_unstable(); v.join(", ") };
            let set = |us: &[&UtxoResponse]| -> Vec<UtxoResponse> { us.iter().map(|u| (*u).clone()).collect() };
            let target = set(&[&m, &t1, &t2]);
            let known = vec![(&m, class("public:0", Origin::Own)), (&t1, box_class(&t1, Origin::Lovejoin)), (&t2, box_class(&t2, Origin::Lovejoin)), (&a, box_class(&a, Origin::Lovejoin)), (&b, box_class(&b, Origin::Lovejoin))];
            for out in [Out::Send, Out::Public, Out::Fund] {
                let most = most_paid(6_100_000, 40_000_000, |l| pays_out(&w, &target, out, l).is_ok());
                let lovelace = most - 20_000;
                let line = format!("{kind}, M {m_ada}, T {t_ada}, A = B {a_ada}: {out:?} of {lovelace} (M, T1, T2 pay up to {most})");
                let premise: Vec<String> = [("M, A, B", set(&[&m, &a, &b])), ("M, A, T1", set(&[&m, &a, &t1])), ("M, B, T1", set(&[&m, &b, &t1])), ("M, A, T2", set(&[&m, &a, &t2])), ("M, B, T2", set(&[&m, &b, &t2]))]
                    .into_iter().filter_map(|(what, i)| match pays_out(&w, &i, out, lovelace) { Err(e) if build::is_short(&e) => None, r => Some(format!("{what}: {r:?}")) }).collect();
                if !premise.is_empty() { skipped.push(line); continue; }
                checked += 1;
                match picked_out(&w, &known, out, lovelace) {
                    Ok(s) if outpoints(&s) == outpoints(&target) => {}
                    Ok(s) => wrong.push(format!("{line}: spent {}, where M, T1 and T2 pay", called(&s))),
                    Err(e) => wrong.push(format!("{line}: refused: {e}")),
                }
            }
        }
    }
    println!("checked {checked}, wrong {}, skipped {}", wrong.len(), skipped.len());
    assert!(checked > 0);
    assert!(wrong.is_empty(), "three boxes merged where two token boxes sharing one new change output pay:\n{}", wrong.join("\n"));
}
