#[test]
fn l8ref1_of_as_many_boxes_beside_what_as_change_keeps_the_mixed_one_goes() {
    let w = world();
    let p = &w.chain.params;
    let m = owned(&w, 0x25, 0, 10_000_000, &[("pooltoken", 1)]);
    let t = owned(&w, 0x76, 0, 6_500_000, &[("pooltoken", 1)]);
    let x = owned(&w, 0x35, 0, 6_400_000, &[]);
    let weight = |u: &UtxoResponse, kept: &build::Kept| {
        build::box_weight(p, &box_class(u, Origin::Lovejoin), &[u], build::Weighed::InOne(kept)).0
    };
    let (nothing, keeps) = (build::Kept::nothing(p), build::Kept::new(p, tokens_of(&[("pooltoken", 1)])));
    let (by_ada, by_kept) = (weight(&t, &nothing), weight(&t, &keeps));
    assert!(by_ada < 6_400_000 && 6_400_000 < by_kept, "X's ADA between T's two weights: {by_ada}, {by_kept}");
    let names = [(&m, "M"), (&t, "T"), (&x, "X")];
    let (mx, mt) = (vec![m.clone(), x.clone()], vec![m.clone(), t.clone()]);
    let mut wrong = Vec::new();
