    let parts = api::build_transfer_parts(sk, request(&w, w.utxos.clone())).unwrap();
    let shown = show(&w, &parts);
    let carries: Vec<bool> = parts.iter().map(|p| p.carry.is_some()).collect();
    let chain_from = carries.iter().position(|c| *c).expect("the payment goes as a chain of parts");
    let received_at = parts.iter().position(|p| spends(p, &w.received.tx_hash));
    let last_own = (chain_from..parts.len()).filter(|&n| shown[n].iter().any(|l| l.starts_with("own bundle"))).max().unwrap();
    // privacy.md:173 / policy:93: in a chain, by history first (Purpose::Pay: own 0, received 2)
